import java.util.*;

public class Main {
    enum Propagation { REQUIRED, REQUIRES_NEW, NESTED }

    interface TxCallable<T> { T call() throws Exception; }

    static class BusinessException extends Exception {
        BusinessException(String message) { super(message); }
    }

    static class UnexpectedRollbackException extends RuntimeException {
        UnexpectedRollbackException(String message) { super(message); }
    }

    static class Tx {
        final String name;
        final List<String> operations = new ArrayList<>();
        boolean rollbackOnly;
        Tx(String name) { this.name = name; }
    }

    static class MiniTxManager {
        private final Deque<Tx> active = new ArrayDeque<>();
        private final Deque<Tx> suspended = new ArrayDeque<>();
        private final List<String> committed = new ArrayList<>();

        List<String> committed() { return new ArrayList<>(committed); }

        void addOperation(String op) {
            Tx tx = active.peek();
            if (tx == null) throw new IllegalStateException("no transaction");
            tx.operations.add(op);
        }

        <T> T run(String name, Propagation propagation, Set<Class<? extends Throwable>> rollbackFor,
                 TxCallable<T> action) throws Exception {
            Tx suspendedTx = null;
            Tx tx;
            boolean owner = false;
            Integer savepoint = null;

            if (propagation == Propagation.REQUIRES_NEW) {
                if (!active.isEmpty()) {
                    suspendedTx = active.pop();
                    suspended.push(suspendedTx);
                }
                tx = begin(name);
                owner = true;
            } else if (propagation == Propagation.NESTED && !active.isEmpty()) {
                tx = active.peek();
                savepoint = tx.operations.size();
            } else if (active.isEmpty()) {
                tx = begin(name);
                owner = true;
            } else {
                tx = active.peek();
            }

            try {
                T result;
                try {
                    result = action.call();
                } catch (Throwable ex) {
                    if (shouldRollback(ex, rollbackFor)) {
                        if (savepoint != null) {
                            rollbackToSavepoint(tx, savepoint);
                        } else if (owner) {
                            rollbackOwner(tx);
                        } else {
                            tx.rollbackOnly = true;
                        }
                    } else if (owner) {
                        commitOwner(tx);
                    }
                    throw ex;
                }
                if (owner) commitOwner(tx);
                return result;
            } finally {
                if (suspendedTx != null) {
                    Tx restored = suspended.pop();
                    active.push(restored);
                }
            }
        }

        private Tx begin(String name) {
            Tx tx = new Tx(name);
            active.push(tx);
            return tx;
        }

        private void commitOwner(Tx tx) {
            if (tx.rollbackOnly) {
                rollbackOwner(tx);
                throw new UnexpectedRollbackException(tx.name + " was marked rollback-only");
            }
            removeActive(tx);
            committed.addAll(tx.operations);
        }

        private void rollbackOwner(Tx tx) {
            removeActive(tx);
            tx.operations.clear();
        }

        private void removeActive(Tx tx) {
            if (active.peek() == tx) active.pop();
            else active.remove(tx);
        }

        private void rollbackToSavepoint(Tx tx, int savepoint) {
            while (tx.operations.size() > savepoint) {
                tx.operations.remove(tx.operations.size() - 1);
            }
        }

        private boolean shouldRollback(Throwable ex, Set<Class<? extends Throwable>> rollbackFor) {
            if (ex instanceof RuntimeException || ex instanceof Error) return true;
            for (Class<? extends Throwable> type : rollbackFor) {
                if (type.isInstance(ex)) return true;
            }
            return false;
        }
    }

    static Set<Class<? extends Throwable>> noRollbackRules() {
        return Set.<Class<? extends Throwable>>of();
    }

    static void requiredRollbackOnlyCase() throws Exception {
        MiniTxManager tx = new MiniTxManager();
        try {
            tx.run("outer", Propagation.REQUIRED, noRollbackRules(), () -> {
                tx.addOperation("outer-before");
                try {
                    tx.run("innerRequired", Propagation.REQUIRED, noRollbackRules(), () -> {
                        tx.addOperation("inner-change");
                        throw new RuntimeException("inner failed");
                    });
                } catch (RuntimeException ignored) {
                    tx.addOperation("outer-caught");
                }
                tx.addOperation("outer-after");
                return null;
            });
        } catch (UnexpectedRollbackException ex) {
            System.out.println("required outcome=" + ex.getClass().getSimpleName() + ", committed=" + tx.committed());
        }
        assert tx.committed().isEmpty();
    }

    static void requiresNewCase() throws Exception {
        MiniTxManager tx = new MiniTxManager();
        try {
            tx.run("createOrder", Propagation.REQUIRED, noRollbackRules(), () -> {
                tx.addOperation("order#1");
                tx.run("audit", Propagation.REQUIRES_NEW, noRollbackRules(), () -> {
                    tx.addOperation("audit#1");
                    return null;
                });
                throw new RuntimeException("payment failed");
            });
        } catch (RuntimeException ignored) {
            System.out.println("requires_new committed=" + tx.committed());
        }
        assert tx.committed().equals(List.of("audit#1"));
    }

    static void nestedCase() throws Exception {
        MiniTxManager tx = new MiniTxManager();
        tx.run("batch", Propagation.REQUIRED, noRollbackRules(), () -> {
            tx.addOperation("batch-start");
            try {
                tx.run("importItem", Propagation.NESTED, noRollbackRules(), () -> {
                    tx.addOperation("bad-item");
                    throw new RuntimeException("bad row");
                });
            } catch (RuntimeException ignored) {
                tx.addOperation("skip-bad-item");
            }
            tx.addOperation("batch-end");
            return null;
        });
        System.out.println("nested committed=" + tx.committed());
        assert tx.committed().equals(List.of("batch-start", "skip-bad-item", "batch-end"));
    }

    static void checkedExceptionCase() throws Exception {
        MiniTxManager defaultRule = new MiniTxManager();
        try {
            defaultRule.run("checkedDefault", Propagation.REQUIRED, noRollbackRules(), () -> {
                defaultRule.addOperation("checked-default");
                throw new BusinessException("business checked exception");
            });
        } catch (BusinessException ignored) { }

        MiniTxManager rollbackFor = new MiniTxManager();
        try {
            rollbackFor.run("checkedRollbackFor", Propagation.REQUIRED,
                Set.<Class<? extends Throwable>>of(BusinessException.class), () -> {
                    rollbackFor.addOperation("checked-rollback-for");
                    throw new BusinessException("business checked exception");
                });
        } catch (BusinessException ignored) { }

        System.out.println("checked default=" + defaultRule.committed() + ", rollbackFor=" + rollbackFor.committed());
        assert defaultRule.committed().equals(List.of("checked-default"));
        assert rollbackFor.committed().isEmpty();
    }

    public static void main(String[] args) throws Exception {
        requiredRollbackOnlyCase();
        requiresNewCase();
        nestedCase();
        checkedExceptionCase();
    }
}
